        { condition: pair("Pooled 성능만 좋아지고 within-duty rank가 실패한다.", "Only pooled performance improves while within-duty rank fails."), action: pair("Domain classifier로 간주하고 RUL predictor 승격을 중단한다.", "Treat it as a domain classifier and stop promotion to an RUL predictor."), meaning: pair("Regime 분류이지 cell 예측이 아니다.", "It is regime classification, not cell prediction") },
        { condition: pair("Electrochemical derivative도 실패하지만 mechanical proxy가 residual을 줄인다.", "The electrochemical derivative fails but a mechanical proxy reduces residuals."), action: pair("Expansion·pressure·ultrasound arm을 독립 target에서 반복한다.", "Replicate expansion, pressure, or ultrasound on an independent target."), meaning: pair("숨은 상태가 전기보다 기계 축에 가깝다.", "The hidden state lies closer to a mechanical than electrical axis") }
